const express = require('express');
const axios = require('axios');

const app = express();
const TEMPO_BASE_URL = process.env.TEMPO_BASE_URL || 'http://tempo:3200';

app.get('/api/observability/traces/:traceId', async (req, res) => {
  const { traceId } = req.params;

  try {
    const response = await axios.get(`${TEMPO_BASE_URL}/api/traces/${traceId}`);
    const traceData = response.data;

    if (!traceData || !traceData.batches) {
      return res.status(404).json({ error: 'Trace not found' });
    }

    // Verify all span resource attributes strictly match the caller's organization boundary
    const isAuthorized = traceData.batches.every(batch => {
      const tenantAttr = batch.resource?.attributes?.find(a => a.key === 'tenant.id');
      return tenantAttr && tenantAttr.value?.stringValue === req.user.organizationId;
    });

    if (!isAuthorized) {
      return res.status(403).json({ error: 'Access denied: Trace belongs to another tenant' });
    }

    return res.json({ traceId, spans: traceData.batches });
  } catch (err) {
    return res.status(500).json({ error: 'Failed to retrieve trace data' });
  }
});

module.exports = app;
